import sys
from abc import ABC, abstractmethod


class Shape(ABC):
    def __init__(self, name, *dims):
        self.name = name
        self.dims = dims

    @property
    @abstractmethod
    def corners(self):
        ...

    @abstractmethod
    def double_area(self):
        ...


class Square(Shape):
    corners = 4

    def double_area(self):
        return 2 * self.dims[0] ** 2


class Rect(Shape):
    corners = 4

    def double_area(self):
        return 2 * self.dims[0] * self.dims[1]


class RTri(Shape):
    corners = 3

    def double_area(self):
        return self.dims[0] * self.dims[1]


class Trap(Shape):
    corners = 4

    def double_area(self):
        a, b, h = self.dims
        return (a + b) * h


KINDS = {"square": Square, "rect": Rect, "rtri": RTri, "trap": Trap}


def main():
    shapes = []
    for line in sys.stdin:
        p = line.split()
        if not p or p[0] not in KINDS:
            continue
        shapes.append(KINDS[p[0]](p[0], *map(int, p[1:])))
    total = 0
    best = None
    for s in shapes:
        d = s.double_area()
        total += d
        print(f"{s.name} corners={s.corners} area2={d}")
        if best is None or d > best[1]:
            best = (s.name, d)
    print(f"total area2={total}")
    if best:
        print(f"largest={best[0]} area2={best[1]}")
    else:
        print("largest=none")


main()
